398	    private string DescribeFactoryResetError(FactoryResetException error)
399	    {
400	        var stage = error.Stage switch
401	        {
402	            "stage-data" => _i18n?.T("暂存应用数据") ?? error.Stage,
403	            "delete-credentials" => _i18n?.T("删除 API 凭据") ?? error.Stage,
404	            "delete-data" => _i18n?.T("删除应用数据") ?? error.Stage,
405	            "delete-residual-data" => _i18n?.T("清理残留数据") ?? error.Stage,
406	            _ => error.Stage,
407	        };
408	        var recovery = error.RollbackComplete
409	            ? _i18n?.T("原数据已保留") ?? "Original data was preserved"
410	            : error.Stage == "delete-credentials" && error.ResidualPath is null
411	                ? _i18n?.T("应用数据已恢复，但部分 API 凭据可能已删除；请重新启动后重试")
412	                    ?? "Application data was restored, but some API credentials may have been deleted"
413	                : _i18n?.T("部分数据可能已暂存，请保留现场并重试")
414	                    ?? "Some data may be staged; preserve the current state and retry";
415	        return _i18n?.Format("恢复出厂失败：{0}；{1}", stage, recovery)
416	            ?? $"Factory reset failed: {stage}; {recovery}";
417	    }
