419	    private void RestartApplication()
420	    {
421	        var executable = Environment.ProcessPath
422	            ?? throw new InvalidOperationException("Unable to determine the application path");
423	        using var current = Process.GetCurrentProcess();
424	        var startTicks = current.StartTime.ToUniversalTime().Ticks.ToString(System.Globalization.CultureInfo.InvariantCulture);
425	        var startInfo = new ProcessStartInfo(executable) { UseShellExecute = true };
426	        startInfo.ArgumentList.Add("--wait-for-parent");
427	        startInfo.ArgumentList.Add(Environment.ProcessId.ToString(System.Globalization.CultureInfo.InvariantCulture));
428	        startInfo.ArgumentList.Add(startTicks);
429	        Process.Start(startInfo);
430	        Shutdown(0);
435	        if (args.Count != 3 || !string.Equals(args[0], "--wait-for-parent", StringComparison.Ordinal)) return;
436	        if (!int.TryParse(args[1], out var parentId)
437	            || !long.TryParse(args[2], out var expectedStartTicks)
438	            || parentId == Environment.ProcessId)
439	        {
440	            throw new InvalidOperationException("Invalid restart parent identity");
441	        }
442	
443	        using var parent = Process.GetProcessById(parentId);
444	        if (!string.Equals(parent.ProcessName, "DesktopPet.App", StringComparison.OrdinalIgnoreCase)
445	            || parent.StartTime.ToUniversalTime().Ticks != expectedStartTicks)
446	        {
447	            throw new InvalidOperationException("Restart parent identity mismatch");
448	        }
449	        if (!parent.HasExited && !parent.WaitForExit(15_000))
450	            throw new TimeoutException("Restart parent did not exit");
451	    }
