  12	public static class FullscreenBoundsEvaluator
  13	{
  14	    public static bool CoversMonitor(
  15	        ScreenRect window,
  16	        ScreenRect monitor,
  17	        bool maximized,
  18	        int tolerance = 2)
  19	    {
  20	        if (window.Width <= 0 || window.Height <= 0) return false;
  21	        if (maximized) return true;
  22	        return Math.Abs(window.Left - monitor.Left) <= tolerance
  23	            && Math.Abs(window.Top - monitor.Top) <= tolerance
  24	            && Math.Abs(window.Right - monitor.Right) <= tolerance
  25	            && Math.Abs(window.Bottom - monitor.Bottom) <= tolerance;
  26	    }
  27	}
