  38	public sealed class FullscreenWindowDetector
  39	{
  40	    private const uint MonitorDefaultToNearest = 2;
  41	    private readonly int _ownProcessId;
  42	
  43	    public FullscreenWindowDetector(int? ownProcessId = null)
  44	    {
  45	        _ownProcessId = ownProcessId ?? Environment.ProcessId;
  46	    }
  47	
  48	    public bool IsSuppressed()
  49	    {
  50	        var foreground = GetForegroundWindow();
  51	        if (foreground == IntPtr.Zero || !IsWindowVisible(foreground) || IsIconic(foreground)) return false;
  52	        GetWindowThreadProcessId(foreground, out var processId);
  53	        if (processId == _ownProcessId) return false;
  54	
  55	        var monitor = MonitorFromWindow(foreground, MonitorDefaultToNearest);
  56	        if (monitor == IntPtr.Zero) return false;
  57	        var info = new MonitorInfo { CbSize = Marshal.SizeOf<MonitorInfo>() };
  58	        if (!GetMonitorInfo(monitor, ref info)) return false;
  59	
  60	        if (!GetWindowRect(foreground, out var windowRect)) return false;
  61	        var dpi = GetDpiForWindow(foreground);
  62	        var tolerance = Math.Max(2, (int)Math.Round(2d * dpi / 96d));
  63	        var window = new ScreenRect(windowRect.Left, windowRect.Top, windowRect.Right, windowRect.Bottom);
  64	        var bounds = new ScreenRect(
  65	            info.Monitor.Left,
  66	            info.Monitor.Top,
  67	            info.Monitor.Right,
  68	            info.Monitor.Bottom);
  69	        return FullscreenBoundsEvaluator.CoversMonitor(window, bounds, IsZoomed(foreground), tolerance);
  70	    }
