 118	public sealed class FullscreenSuppressionMonitor : IDisposable
 119	{
 120	    private readonly Func<bool> _detect;
 121	    private readonly Action<bool> _publish;
 122	    private readonly TimeSpan _interval;
 123	    private DispatcherTimer? _timer;
 124	    private bool? _lastValue;
 125	    private bool _disposed;
 126	
 127	    public FullscreenSuppressionMonitor(
 128	        Func<bool> detect,
 129	        Action<bool> publish,
 130	        TimeSpan? interval = null)
 131	    {
 132	        _detect = detect;
 133	        _publish = publish;
 134	        _interval = interval ?? TimeSpan.FromMilliseconds(250);
 135	        if (_interval <= TimeSpan.Zero) throw new ArgumentOutOfRangeException(nameof(interval));
 136	    }
 137	
 138	    public bool IsRunning => _timer?.IsEnabled == true;
 139	
 140	    public void Start()
 141	    {
 142	        ObjectDisposedException.ThrowIf(_disposed, this);
 143	        if (_timer is not null) return;
 144	        _timer = new DispatcherTimer { Interval = _interval };
 145	        _timer.Tick += OnTick;
 146	        _timer.Start();
 147	        Poll();
 148	    }
 149	
 150	    public void Poll()
 151	    {
 152	        ObjectDisposedException.ThrowIf(_disposed, this);
 153	        var value = _detect();
 154	        if (_lastValue == value) return;
 155	        _lastValue = value;
 156	        _publish(value);
 157	    }
 158	
 159	    public void Stop()
 160	    {
 161	        if (_timer is null) return;
 162	        _timer.Stop();
 163	        _timer.Tick -= OnTick;
 164	        _timer = null;
 165	    }
 166	
 167	    public void Dispose()
 168	    {
 169	        if (_disposed) return;
 170	        Stop();
 171	        _disposed = true;
 172	    }
 173	
 174	    private void OnTick(object? sender, EventArgs e) => Poll();
 175	}
