  5	public sealed class FactoryResetException : IOException
  6	{
  7	    public FactoryResetException(
  8	        string stage,
  9	        string? residualPath,
 10	        bool rollbackComplete,
 11	        Exception innerException)
 12	        : base($"Factory reset failed during {stage}", innerException)
 13	    {
 14	        Stage = stage;
 15	        ResidualPath = residualPath;
 16	        RollbackComplete = rollbackComplete;
 17	    }
 18	
 19	    public string Stage { get; }
 20	    public string? ResidualPath { get; }
 21	    public bool RollbackComplete { get; }
 22	}
 23	
 24	public sealed record FactoryResetResult(bool DataDirectoryExisted, int CredentialsDeleted);
 25	
 26	public sealed class FactoryResetService
 27	{
 28	    private readonly string _root;
 29	    private readonly ICredentialNamespaceCleaner _credentials;
 30	
 31	    public FactoryResetService(string root, ICredentialNamespaceCleaner credentials)
 32	    {
 33	        ArgumentException.ThrowIfNullOrWhiteSpace(root);
 34	        _root = Path.TrimEndingDirectorySeparator(Path.GetFullPath(root));
 35	        if (string.Equals(_root, Path.GetPathRoot(_root), StringComparison.OrdinalIgnoreCase)
 36	            || Directory.GetParent(_root) is null)
 37	        {
 38	            throw new ArgumentException("The reset root must be a non-root directory", nameof(root));
 39	        }
 40	        _credentials = credentials;
 41	    }
 42	
 43	    public FactoryResetResult Reset()
 44	    {
 45	        RejectReparsePoint();
 46	        var existed = Directory.Exists(_root);
 47	        string? staged = null;
 48	        if (existed)
 49	        {
 50	            staged = _root + ".reset-" + Guid.NewGuid().ToString("N");
 51	            try { Directory.Move(_root, staged); }
 52	            catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
 53	            {
 54	                throw new FactoryResetException("stage-data", _root, rollbackComplete: true, ex);
 55	            }
 56	        }
 57	
 58	        int deleted;
 59	        try
 60	        {
 61	            deleted = _credentials.DeleteAll();
 62	        }
 63	        catch (IOException ex)
 64	        {
 65	            var dataRestored = RestoreStagedData(staged);
 66	            throw new FactoryResetException(
 67	                "delete-credentials",
 68	                dataRestored ? null : staged,
 69	                rollbackComplete: false,
 70	                ex);
 71	        }
 72	
 73	        if (staged is not null)
 74	        {
 75	            try { Directory.Delete(staged, recursive: true); }
 76	            catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
 77	            {
 78	                throw new FactoryResetException(
 79	                    "delete-data",
 80	                    staged,
 81	                    rollbackComplete: false,
 82	                    ex);
 83	            }
