 26	public sealed class FactoryResetService
 27	{
 28	    private readonly string _root;
 29	    private readonly ICredentialNamespaceCleaner _credentials;
 30	
 31	    public FactoryResetService(string root, ICredentialNamespaceCleaner credentials)
 32	    {
 33	        ArgumentException.ThrowIfNullOrWhiteSpace(root);
 34	        _root = Path.TrimEndingDirectorySeparator(Path.GetFullPath(root));
 35	        if (string.Equals(_root, Path.GetPathRoot(_root), StringComparison.OrdinalIgnoreCase)
 36	            || Directory.GetParent(_root) is null)
