 44	    {
 45	        RejectReparsePoint();
 46	        var existed = Directory.Exists(_root);
 47	        string? staged = null;
 48	        if (existed)
 49	        {
 50	            staged = _root + ".reset-" + Guid.NewGuid().ToString("N");
 51	            try { Directory.Move(_root, staged); }
 52	            catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
 53	            {
 54	                throw new FactoryResetException("stage-data", _root, rollbackComplete: true, ex);
 55	            }
 56	        }
 57	
 58	        int deleted;
 59	        try
 60	        {
 61	            deleted = _credentials.DeleteAll();
 62	        }
 63	        catch (IOException ex)
 64	        {
 65	            var dataRestored = RestoreStagedData(staged);
 66	            throw new FactoryResetException(
 67	                "delete-credentials",
 68	                dataRestored ? null : staged,
 69	                rollbackComplete: false,
 70	                ex);
 71	        }
 72	
 73	        if (staged is not null)
 74	        {
 75	            try { Directory.Delete(staged, recursive: true); }
 76	            catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
 77	            {
 78	                throw new FactoryResetException(
 79	                    "delete-data",
 80	                    staged,
 81	                    rollbackComplete: false,
 82	                    ex);
 83	            }
 84	        }
 85	        DeletePriorResiduals();
 86	        return new FactoryResetResult(existed, deleted);
 87	    }
